<script setup>
import {computed} from 'vue'
const props=defineProps({color:{default:'#86c7a1'},role:{default:'suspect'},emotion:{default:'idle'},label:String})
const pattern=['.....BB..BB.....','....BbbBBbbB....','...BbbbbbbbbB...','..BbbbbbbbbbbB..','..BbbWWbbWWbbB..','..BbbKKbbKKbbB..','..BbbbbbbbbbbB..','...BbbbPPbbbB...','..BbbbbbbbbbbB..','.BbbbbbLLbbbbbB.','.BbbbbLLLLbbbbB.','..BbbbbLLbbbbB..','...BbbbbbbbbB...','...BbbbBBbbbB...','..BbbbbBBbbbbB..','...BBBB..BBBB...']
const pixels=computed(()=>pattern.flatMap((row,y)=>[...row].flatMap((v,x)=>v==='.'?[]:[{x,y,color:{B:'#203043',b:props.color,W:'#fff9e8',K:'#182637',P:'#e3859c',L:'#f8e5aa'}[v]}])))
</script>
<template><span :class="['sql-monster',emotion,role]" :aria-label="label"><svg viewBox="0 -5 16 22" role="img" :aria-label="label||role" shape-rendering="crispEdges"><rect v-for="p in pixels" :key="p.x+':'+p.y" :x="p.x" :y="p.y" width="1" height="1" :fill="p.color"/><g v-if="role==='detective'"><path d="M3 0V-3H6V-4H11V0H14V2H1V0Z" fill="#203043"/><path d="M4 -2H11V0H4Z" fill="#d8b768"/><rect x="11" y="10" width="4" height="4" fill="#a8e2e5" stroke="#263e50" stroke-width="1"/><rect x="14" y="14" width="1" height="3" fill="#d8b768"/></g><path v-if="role==='witness'" d="M2 0H14V2H2Z" fill="#f5e5c6"/><path v-if="emotion==='surprised'||emotion==='panic'" d="M7 -5H9V-2H7ZM7 -1H9V0H7Z" fill="#ffe381"/></svg><span v-if="emotion==='think'" class="thought">?</span><span v-if="emotion==='joy'" class="happy">♥</span></span></template>
<style scoped>.sql-monster{display:inline-block;position:relative;width:72px;height:96px;flex:none;filter:drop-shadow(0 3px 0 #17263840)}svg{width:100%;height:100%;overflow:visible;image-rendering:pixelated}.walk,.run{animation:sql-step .48s steps(2,end) infinite}.run{animation-duration:.24s}.surprised{animation:sql-hop .5s ease-out}.panic{animation:sql-panic .55s ease-in-out 2}.joy{animation:sql-hop .7s ease-in-out 3}.think{animation:sql-think 1s ease-in-out 2}.thought,.happy{position:absolute;top:0;right:0;font-size:22px;color:#ffe08c;font-weight:bold}.happy{color:#ee9ab2}@keyframes sql-step{50%{transform:translateY(-4px) rotate(3deg)}}@keyframes sql-hop{50%{transform:translateY(-10px)}}@keyframes sql-panic{25%{transform:rotate(-6deg)}75%{transform:rotate(6deg)}}@keyframes sql-think{50%{transform:rotate(-5deg)}}@media(prefers-reduced-motion:reduce){.sql-monster{animation:none!important}}</style>
